// Checkout conversion module - ensures paidEvents increment on successful payment
const { logEvent } = require('./eventLogger');

async function processCheckout(session) {
  // Simulate payment processing
  const success = Math.random() > 0.3; // 70% conversion for testing
  if (success) {
    await logEvent('paidEvent', { sessionId: session.id, amount: session.amount });
    return { status: 'success', paid: true };
  }
  return { status: 'failed', paid: false };
}

module.exports = { processCheckout };
